def get_max_sum(n: int) -> int:
    memo = {}

    def f(x: int) -> int:
        if x == 0:
            return 0
        if x in memo:
            return memo[x]
        # f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n)
        # Using integer division as implied by the problem statement
        split_sum = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)
        result = max(split_sum, x)
        memo[x] = result
        return result

    return f(n)

# Example assertion
assert get_max_sum(60) == 106
